import { PRIMARY_SITE_ORIGIN } from "./public-site-identity.mjs";

// These routes were generated by the former mass-indexing strategy. They must
// be deleted from source rather than merely removed from sitemap.xml: the
// static builder publishes every tracked deployable file.
const RETIRED_ARABIC_COLLECTION_SLUGS = Object.freeze([
  "alghaz-ma-alhal",
  "alghaz-lil-atfal-ma-alhal",
  "alghaz-mantiqiyya-ma-alhal",
  "asila-amma-wa-ajwiba",
  "ikhtibar-spacetoon",
  "ikhtibar-qawanin-korat-alqadam",
]);

const RETIRED_SEO_ARTIFACT_PATTERNS = Object.freeze([
  /^en\//iu,
  /^[a-z0-9-]+\/page\/\d+\/index\.html$/iu,
  /^ar\/topics\/[a-z0-9-]+\/page\/\d+\/index\.html$/iu,
  new RegExp(`^ar/(?:${RETIRED_ARABIC_COLLECTION_SLUGS.join("|")})/index\\.html$`, "iu"),
]);

const TEXT_ARTIFACT_EXTENSION = /\.(?:css|html|js|json|map|mjs|svg|txt|webmanifest|xml)$/iu;
const RETIRED_PUBLIC_HOST = /(?:https?|wss?):\/\/(?:www\.)?jakh\.net(?=[:/?#]|$)|(?:https?|wss?):\/\/api\.jakh\.net(?=[:/?#]|$)|\/\/api\.jakh\.net(?=[:/?#]|$)|\/\/(?:www\.)?jakh\.net(?=[:/?#]|$)/iu;
// Internal cache keys, event names, and database-compatible identifiers remain
// lowercase `jakh-*` during the migration.  Only public display copy uses the
// historical uppercase brand and must never reach a release artifact.
const RETIRED_BRAND_COPY = /\bJAKH(?:\.NET| Riddles)?\b/u;
const RETIRED_BRAND_ASSET_REFERENCE = /(?:^|[^A-Za-z0-9_.-])\/?assets\/(?:logo\.(?:png|webp)|og-image\.jpg|riddlearabia-mark\.svg)(?=$|[?#/"'\s<)])/iu;

function invariant(condition, message) {
  if (!condition) throw new Error(message);
}

function normalizePath(value) {
  return String(value || "").replaceAll("\\", "/").replace(/^\.\//u, "").replace(/^\/+|\/+$/gu, "");
}

function textFrom(bytes) {
  return Buffer.isBuffer(bytes) ? bytes.toString("utf8") : String(bytes ?? "");
}

function attributes(tag) {
  const result = new Map();
  const pattern = /([^\s"'<>/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/gu;
  const opening = String(tag).match(/^<[^\s/>]+/u)?.[0] || "";
  for (const match of String(tag).slice(opening.length).matchAll(pattern)) {
    if (!result.has(match[1].toLowerCase())) {
      result.set(match[1].toLowerCase(), match[2] ?? match[3] ?? match[4] ?? "");
    }
  }
  return result;
}

function tagValues(source, name) {
  const pattern = new RegExp(`<${name}\\b(?:[^>\"']|\"[^\"]*\"|'[^']*')*>`, "giu");
  return [...String(source).matchAll(pattern)].map((match) => ({
    raw: match[0],
    attributes: attributes(match[0]),
  }));
}

function isNoindex(source) {
  return tagValues(source, "meta").some((tag) => (
    tag.attributes.get("name")?.toLowerCase() === "robots"
      && /(?:^|[\s,])noindex(?:$|[\s,])/iu.test(tag.attributes.get("content") || "")
  ));
}

function canonicalUrl(source, relativePath) {
  const canonicals = tagValues(source, "link").filter((tag) => (
    (tag.attributes.get("rel") || "").toLowerCase().split(/\s+/u).includes("canonical")
  ));
  invariant(canonicals.length === 1, `${relativePath}: indexable HTML must declare exactly one canonical`);
  const canonical = canonicals[0];
  const href = canonical.attributes.get("href") || "";
  let parsed;
  try {
    parsed = new URL(href);
  } catch {
    throw new Error(`${relativePath}: canonical is not an absolute URL: ${href || "missing"}`);
  }
  invariant(
    parsed.origin === PRIMARY_SITE_ORIGIN && !parsed.search && !parsed.hash,
    `${relativePath}: canonical must use ${PRIMARY_SITE_ORIGIN} without a query or fragment`,
  );
  return parsed.href;
}

function sitemapUrls(source) {
  const urls = [];
  for (const match of String(source).matchAll(/<loc\b[^>]*>([\s\S]*?)<\/loc>/giu)) {
    urls.push(match[1].replaceAll("&amp;", "&").trim());
  }
  for (const tag of tagValues(source, "xhtml:link")) {
    const href = tag.attributes.get("href");
    if (href) urls.push(href.replaceAll("&amp;", "&").trim());
  }
  return urls;
}

function validatedPrimaryUrl(value, label) {
  let parsed;
  try {
    parsed = new URL(value);
  } catch {
    throw new Error(`${label}: invalid absolute URL: ${value || "missing"}`);
  }
  invariant(
    parsed.origin === PRIMARY_SITE_ORIGIN && !parsed.search && !parsed.hash,
    `${label}: must use ${PRIMARY_SITE_ORIGIN} without a query or fragment`,
  );
  return parsed.href;
}

function difference(left, right) {
  return [...left].filter((value) => !right.has(value)).sort((a, b) => a.localeCompare(b, "en"));
}

export function isRetiredPublicSeoArtifactPath(relativePath) {
  const normalized = normalizePath(relativePath);
  return RETIRED_SEO_ARTIFACT_PATTERNS.some((pattern) => pattern.test(normalized));
}

/**
 * Validates the exact bytes that will be deployed. This is intentionally
 * independent of the source generators: a deleted sitemap entry alone must
 * never leave a former SEO page in the release inventory.
 */
export function assertPublicSeoReleaseSafety(artifactBytes, { requireMetadata = false } = {}) {
  invariant(artifactBytes instanceof Map, "public SEO release validation needs an artifact byte map");
  const retiredPaths = [...artifactBytes.keys()]
    .map(normalizePath)
    .filter(isRetiredPublicSeoArtifactPath)
    .sort((a, b) => a.localeCompare(b, "en"));
  invariant(
    retiredPaths.length === 0,
    `Retired SEO artifact(s) would be published: ${retiredPaths.join(", ")}. Delete them from the repository.`,
  );

  const indexedCanonicals = new Set();
  for (const [rawRelativePath, bytes] of artifactBytes) {
    const relativePath = normalizePath(rawRelativePath);
    if (!TEXT_ARTIFACT_EXTENSION.test(relativePath)) continue;
    const source = textFrom(bytes);
    invariant(!RETIRED_PUBLIC_HOST.test(source), `${relativePath}: retains a legacy jakh.net public host`);
    invariant(!RETIRED_BRAND_COPY.test(source), `${relativePath}: retains legacy JAKH public copy`);
    invariant(!RETIRED_BRAND_ASSET_REFERENCE.test(source), `${relativePath}: retains a retired public brand asset reference`);

    if (!relativePath.endsWith(".html") || relativePath === "404.html" || isNoindex(source)) continue;
    const canonical = canonicalUrl(source, relativePath);
    invariant(!indexedCanonicals.has(canonical), `${relativePath}: duplicates an indexable canonical: ${canonical}`);
    indexedCanonicals.add(canonical);
  }

  if (!requireMetadata) return;

  const robots = artifactBytes.get("robots.txt");
  const sitemap = artifactBytes.get("sitemap.xml");
  invariant(robots, "robots.txt is missing from the public release artifact");
  invariant(sitemap, "sitemap.xml is missing from the public release artifact");

  const robotsText = textFrom(robots);
  invariant(/^\s*User-agent\s*:\s*\*\s*$/imu.test(robotsText), "robots.txt must declare User-agent: *");
  invariant(/^\s*Allow\s*:\s*\/\s*$/imu.test(robotsText), "robots.txt must allow the public site root");
  const sitemapDirectives = [...robotsText.matchAll(/^\s*Sitemap\s*:\s*(\S+)\s*$/gimu)];
  invariant(sitemapDirectives.length === 1, "robots.txt must declare exactly one Sitemap directive");
  invariant(
    sitemapDirectives[0][1] === `${PRIMARY_SITE_ORIGIN}/sitemap.xml`,
    `robots.txt Sitemap directive must be ${PRIMARY_SITE_ORIGIN}/sitemap.xml`,
  );

  const sitemapText = textFrom(sitemap);
  const declaredUrls = sitemapUrls(sitemapText).map((value) => validatedPrimaryUrl(value, "sitemap.xml URL"));
  invariant(declaredUrls.length > 0, "sitemap.xml must contain at least one URL");
  const sitemapCanonicals = new Set(
    [...String(sitemapText).matchAll(/<loc\b[^>]*>([\s\S]*?)<\/loc>/giu)]
      .map((match) => validatedPrimaryUrl(match[1].replaceAll("&amp;", "&").trim(), "sitemap.xml <loc>")),
  );
  invariant(sitemapCanonicals.size === [...sitemapText.matchAll(/<loc\b[^>]*>/giu)].length, "sitemap.xml must not repeat <loc> URLs");

  const missingFromSitemap = difference(indexedCanonicals, sitemapCanonicals);
  const staleSitemapUrls = difference(sitemapCanonicals, indexedCanonicals);
  invariant(
    missingFromSitemap.length === 0,
    `Indexable artifact canonical(s) are missing from sitemap.xml: ${missingFromSitemap.join(", ")}`,
  );
  invariant(
    staleSitemapUrls.length === 0,
    `sitemap.xml retains non-indexable or stale artifact URL(s): ${staleSitemapUrls.join(", ")}`,
  );
}
